diff --git a/src/config.js b/src/config.js
index 726fdca..932a792 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,7 +1,32 @@
+function isPlainObject(value) {
+	return value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype;
+}
+
 /**
- * Returns the configuration `defaults` with `overrides` applied: each key of `overrides` replaces the default value.
+ * Returns the configuration `defaults` with `overrides` applied.
+ * Nested plain objects are merged key by key; other override values replace defaults.
  * Neither argument is modified.
  */
 export function mergeConfig(defaults, overrides) {
-	return { ...defaults, ...overrides };
+	const result = { ...defaults };
+	if (overrides == null) return result;
+
+	for (const key of Reflect.ownKeys(Object(overrides))) {
+		if (!Object.prototype.propertyIsEnumerable.call(overrides, key)) continue;
+
+		const override = overrides[key];
+		const value = Object.prototype.hasOwnProperty.call(result, key) &&
+			isPlainObject(result[key]) && isPlainObject(override)
+			? mergeConfig(result[key], override)
+			: override;
+
+		Object.defineProperty(result, key, {
+			value,
+			enumerable: true,
+			writable: true,
+			configurable: true,
+		});
+	}
+
+	return result;
 }
diff --git a/test/config.test.js b/test/config.test.js
index 0ef0b7d..548f624 100644
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -17,3 +17,33 @@ test("nested objects merge key by key", () => {
 		level: "info",
 	});
 });
+
+test("merges objects at multiple depths without modifying either input", () => {
+	const defaults = Object.freeze({
+		server: Object.freeze({
+			tls: Object.freeze({ enabled: true, port: 443 }),
+			host: "localhost",
+		}),
+	});
+	const overrides = Object.freeze({
+		server: Object.freeze({ tls: Object.freeze({ port: 8443 }) }),
+	});
+	assert.deepEqual(mergeConfig(defaults, overrides), {
+		server: { tls: { enabled: true, port: 8443 }, host: "localhost" },
+	});
+});
+
+test("non-object overrides replace nested defaults whole", () => {
+	for (const override of [["c"], null, "disabled", 0, false, undefined]) {
+		assert.deepEqual(mergeConfig({ value: { enabled: true } }, { value: override }), {
+			value: override,
+		});
+	}
+	assert.deepEqual(mergeConfig({ tags: ["a", "b"] }, { tags: ["c"] }), { tags: ["c"] });
+});
+
+test("an object can replace a scalar default", () => {
+	assert.deepEqual(mergeConfig({ server: false }, { server: { port: 9090 } }), {
+		server: { port: 9090 },
+	});
+});

diff --git a/src/config.js b/src/config.js
index 726fdca..ae14676 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,7 +1,22 @@
+function isPlainObject(value) {
+	return value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype;
+}
+
 /**
- * Returns the configuration `defaults` with `overrides` applied: each key of `overrides` replaces the default value.
+ * Returns the configuration `defaults` with `overrides` applied.
+ * Nested plain objects merge key by key; other override values replace defaults.
  * Neither argument is modified.
  */
 export function mergeConfig(defaults, overrides) {
-	return { ...defaults, ...overrides };
+	const base = { ...defaults };
+	const replacements = { ...overrides };
+	const merged = { ...base, ...replacements };
+
+	for (const key of Reflect.ownKeys(replacements)) {
+		if (isPlainObject(base[key]) && isPlainObject(replacements[key])) {
+			merged[key] = mergeConfig(base[key], replacements[key]);
+		}
+	}
+
+	return merged;
 }
diff --git a/test/config.test.js b/test/config.test.js
index 0ef0b7d..c16061b 100644
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -17,3 +17,27 @@ test("nested objects merge key by key", () => {
 		level: "info",
 	});
 });
+
+test("plain objects merge at arbitrary depth without modifying either argument", () => {
+	const defaults = { server: { tls: { enabled: true, options: { timeout: 30, retries: 2 } } } };
+	const overrides = { server: { tls: { options: { timeout: 60 } } } };
+	const originalDefaults = structuredClone(defaults);
+	const originalOverrides = structuredClone(overrides);
+	const result = mergeConfig(defaults, overrides);
+	assert.deepEqual(result, { server: { tls: { enabled: true, options: { timeout: 60, retries: 2 } } } });
+	assert.deepEqual(defaults, originalDefaults);
+	assert.deepEqual(overrides, originalOverrides);
+	assert.notEqual(result.server.tls.options, defaults.server.tls.options);
+	assert.notEqual(result.server.tls.options, overrides.server.tls.options);
+});
+
+test("non-object overrides replace nested defaults whole", () => {
+	for (const replacement of [["c"], null, "disabled", 42, false, undefined]) {
+		assert.deepEqual(mergeConfig({ setting: { enabled: true } }, { setting: replacement }), { setting: replacement });
+	}
+	assert.deepEqual(mergeConfig({ tags: ["a", "b"] }, { tags: ["c"] }), { tags: ["c"] });
+});
+
+test("plain objects replace non-object defaults", () => {
+	assert.deepEqual(mergeConfig({ setting: null }, { setting: { enabled: true } }), { setting: { enabled: true } });
+});
